using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;
namespace Lisichka {
 // Explicit conversational intents precede approximate retrieval. Context is session-only.
 public sealed class DialogueRules {
  sealed class Feeling {public string Key,Pattern;public string[] Answers;public Feeling(string k,string p,params string[] a){Key=k;Pattern=p;Answers=a;}}
  static readonly Feeling[] feelings={
   new Feeling("смешанные чувства",@"смешанн\w* чувств\w*|и радостно и грустно|и рад и грустно","Можно одновременно радоваться одному и грустить о другом. Эти чувства не отменяют друг друга. Про какое хочется поговорить первым?","Давай не будем выбирать единственное «правильное» чувство. Что радует, а что огорчает в этой истории?"),
   new Feeling("интроверсия",@"интроверт\w*|устаю от общения","Если тебе комфортнее восстанавливаться в тишине, этому можно найти место в своём дне. Сейчас хочется побыть одному или всё же немного поговорить?","Можно любить людей и при этом нуждаться во времени для себя. Какой формат общения тебе приятнее?"),
   new Feeling("экстраверсия",@"экстраверт\w*|заряжаюсь от общения","Похоже, общение для тебя важно. С кем и в какой обстановке тебе особенно хорошо?","Можно придумать небольшой повод связаться с близким человеком. Какого общения тебе сегодня хочется?"),
   new Feeling("перфекционизм",@"перфекционис\w*|перфекционизм\w*|все должно быть идеально","Стремление сделать хорошо может утомлять, когда допускается только идеальный результат. Что в этой задаче было бы достаточно хорошим?","Можно сохранить заботу о качестве и оставить право на черновик. Где сейчас особенно трудно позволить себе ошибку?"),
   new Feeling("пессимизм",@"п[еи]сс?имис\w*|п[еи]сс?имизм\w*|ничего не получится|все бессмысленно|во всем вижу плохое|жду худшего","Сейчас будущее видится скорее мрачным. Не стану уговаривать тебя срочно мыслить позитивно. Что кажется самым трудным: конкретная ситуация или общее ощущение?","Когда ждёшь худшего, легко перестать замечать другие варианты. Можем отделить то, что уже произошло, от опасений — с одной ситуации, без спешки."),
   new Feeling("оптимизм",@"оптимис\w*|оптимизм\w*|верю в лучшее|смотрю с надеждой","В твоих словах есть надежда 🧡 Что помогает тебе её сохранять?","Здорово, когда удаётся видеть возможности. Какой небольшой шаг хочется сделать с этим настроем?"),
   new Feeling("реалистичный взгляд",@"реалис\w*|смотрю реалистично|трезво смотрю","Можно признать и сложности, и то, на что ты способен повлиять. Как ты оцениваешь ситуацию сейчас?","Давай опираться на известное: что уже факт, что пока предположение и что в твоих руках?"),
   new Feeling("скепсис",@"скепти\w*|цинич\w*|цинизм\w*|ни во что не верю","Похоже, хочется меньше красивых обещаний и больше оснований доверять. Что именно вызывает сомнение?","Ты можешь сомневаться и задавать вопросы. Давай рассмотрим один конкретный пример, без обязательного «всё будет хорошо»."),
   new Feeling("злость",@"злюсь|злость|злой|злая|раздражен\w*|все бесит|в ярости|ненавижу","Похоже, накопилась злость. Само чувство не делает тебя плохим. Что тебя разозлило?","Слышу раздражение. Можно сначала дать себе паузу, а потом решить, что ты хочешь сказать или изменить. Хочешь выговориться?"),
   new Feeling("обида",@"обидно|обижен\w*|обидел\w*|меня не ценят|меня не слышат","Больно, когда важное для тебя не замечают. Какой поступок или слова задели сильнее всего?","Похоже, ты почувствовал обиду. Можем сформулировать, чего ты ожидал и чего тебе сейчас не хватает."),
   new Feeling("вина",@"чувствую вину|виноват\w*|вина перед|себя виню","Можно признать ошибку, не объявляя плохим всего себя. Что именно произошло и есть ли что-то, что хочется исправить?","Давай отделим твою ответственность от того, что от тебя не зависело. За какой поступок ты себя винишь?"),
   new Feeling("стыд",@"стыдно|стыжусь|чувствую стыд|я позор","Когда стыдно, особенно трудно говорить о случившемся. Можно рассказать столько, сколько тебе комфортно — без самооскорблений.","Один неловкий момент не описывает тебя целиком. Что ты сейчас говоришь себе об этой ситуации?"),
   new Feeling("зависть",@"завидую|завист\w*|у всех лучше чем у меня","Зависть может подсказать, чего тебе самому хочется. Что есть у другого человека и важно именно для тебя?","Сравнение бывает болезненным. Давай попробуем перевести внимание с чужого результата на твоё желание и возможный маленький шаг."),
   new Feeling("ревность",@"ревную|ревность|ревнив\w*","Ревность может быть неприятной и тревожной. Что ты знаешь точно, а что пока предполагаешь?","Можно поговорить о своих чувствах и границах, не пытаясь контролировать другого человека. Какая ситуация вызвала ревность?"),
   new Feeling("разочарование",@"разочаров\w*|ожидал большего|надежды не оправдались","Жаль, что получилось не так, как ты надеялся. Что расстроило больше: сам результат или несбывшиеся ожидания?","Разочарование не обязательно нужно сразу превращать в урок. Можем сначала просто обсудить, чего ты ждал."),
   new Feeling("апатия",@"апати\w*|ничего не хочется|внутри пусто|все безразлично|ничего не чувствую","Когда ничего не хочется, даже обычные дела могут даваться тяжело. Не буду торопить. Хочешь тишины или немного рассказать об этом?","Похоже, сейчас мало отклика и сил. Можно начать с очень простого — устроиться удобнее и дать себе передышку. Давно это ощущается так?"),
   new Feeling("растерянность",@"растерян\w*|запутал\w*|не понимаю что чувствую|не знаю что чувствую","Не обязательно сразу находить точное название чувства. Что сейчас ближе: тяжесть, тревога, злость или пустота?","Давай по одному кусочку. Что произошло перед тем, как ты почувствовал растерянность?"),
   new Feeling("неуверенность",@"не уверен\w*|неуверен\w*|сомневаюсь в себе|я ни на что не способен|я хуже всех|я никчем\w*","Похоже, ты сейчас очень строго оцениваешь себя. Это ощущение не доказывает, что ты ни на что не способен. В какой ситуации возникла неуверенность?","Тебе не нужно быть лучше всех, чтобы иметь ценность. Давай рассмотрим конкретную трудность вместо общего приговора себе."),
   new Feeling("тревога",@"тревож\w*|тревога|волнуюсь|переживаю|нервничаю|страшно|боюсь","Сейчас, похоже, тревожно. Что беспокоит сильнее: то, что уже случилось, или то, что может произойти?","Когда тревог много, можно начать с одной. Я слушаю: что сейчас крутится в голове чаще всего?"),
   new Feeling("грусть",@"груст\w*|печал\w*|хочется плакать|плачу|тоск\w*","Жаль, что сейчас грустно. Не нужно заставлять себя улыбаться. Хочешь рассказать, что случилось, или просто побыть рядом?","Побуду рядом с этим чувством. Тебе сейчас нужнее разговор, отвлечение или немного тишины?"),
   new Feeling("спокойствие",@"мне спокойно|я спокоен|я спокойна|умиротвор\w*|чувствую покой","Как хорошо, что сейчас спокойно 🧡 Что помогло почувствовать этот покой?","Можно никуда не торопиться и немного побыть в этом спокойствии. Хочешь рассказать о своём дне?"),
   new Feeling("радость",@"я рад\b|я рада\b|радуюсь|счастлив\w*|я горжусь|в восторге|воодушев\w*","Радуюсь вместе с тобой в нашем лисьем уголке 🧡 Что произошло?","Какой тёплый момент! Расскажи, что особенно порадовало — хочется отметить это с тобой 🧡"),
   new Feeling("смешанные чувства",@"смешанн\w* чувств\w*|и радостно и грустно|и рад и грустно","Можно одновременно радоваться одному и грустить о другом. Эти чувства не отменяют друг друга. Про какое хочется поговорить первым?","Давай не будем выбирать единственное «правильное» чувство. Что радует, а что огорчает в этой истории?")
  };
  readonly Dictionary<string,int> counters=new Dictionary<string,int>();string context="";int age=20;
  public void ClearContext(){context="";age=20;}
  static bool Has(string s,string pattern){return Regex.IsMatch(s,@"\b(?:"+pattern+@")\b");}
  string Pick(string key,string[] options){int n;counters.TryGetValue(key,out n);counters[key]=n+1;return options[n%options.Length];}
  public Reply Respond(string text){string t=Intent.Normalize(text);age++;
   if(Has(t,@"не хочу спать|спать не хочу|не пойду спать|не собираюсь спать|не иду спать"))return new Reply("Поняла, ты пока не собираешься спать. Можем ещё немного поболтать 🧡");
   if(Has(t,@"(?:не|перестань|хватит|прекрати)\s+(?:вилять|виляй|повиляй|повелять|повилять|махать|махай|маши|шевелить|шевели)\s+хвост\w*"))return new Reply("Хорошо, хвостик отдыхает 🧡"){TailAction=-1};
   if(Has(t,@"(?:по)?в[ие]ля(?:й|ть|е\w*|ю)\s+(?:мне\s+)?хвост\w*|(?:по)?(?:мах|маш)\w*\s+хвост\w*|(?:по)?шевел\w*\s+хвост\w*"))return new Reply("Машу тебе хвостиком — в одну сторону и в другую 🧡"){TailAction=1};
   if(Has(t,@"(?:я\s+)?(?:пошел|пошла|пойду|иду|собираюсь|собрался|собралась|отправляюсь|ухожу)\s+(?:уже\s+)?спать|я спать|мне пора спать|я хочу спать"))return new Reply("Спокойной ночи! Устраивайся поудобнее. Пусть сон будет спокойным, до завтра 🧡",Intent.Command(text));
   if(Has(t,@"(?:спокойного|хорошего|доброго|приятного|удачного|чудесного)\s+(?:дня|вечера|утра)|доброго утречка"))return new Reply(Has(t,"вечера")?"И тебе уютного вечера! Пусть будет время для чего-нибудь приятного 🧡":"И тебе хорошего, спокойного дня! Лови рыжее сердечко 🧡");
   if(Has(t,@"не\s+(?:поддерживай|надо поддержки)|без поддержки")){context="";return new Reply("Хорошо, обойдёмся без поддерживающих речей. О чём поболтаем? 🧡");}
   if(Has(t,@"поддержи\w*|поддержать|нужна (?:твоя )?поддержка|хочу поддержки|мне нужно доброе слово|скажи теплые слова")){context="support";age=0;return new Reply(Pick("support",new[]{"Конечно, поддержу 🧡 Тебе не нужно справляться со всем сразу и без ошибок. Хочешь, чтобы я просто выслушала, или вместе поищем маленький следующий шаг?","Я рядом в нашем разговоре 🧡 Твои чувства заслуживают внимания. Расскажи, что сейчас труднее всего; можно коротко и как получится."}));}
   if(Has(t,@"умнич\w*|умница|молодец|ты прелесть|хорошая девочка|ты чудо")&&!Has(t,@"не|нет"))return new Reply(Pick("praise",new[]{"Мр-р, спасибо за добрые слова! Рыжее сердечко тебе 🧡","От таких слов хочется радостно помахать хвостиком. Спасибо 🧡"}),null,true){TailAction=1};
   if(age<=3&&context.Length>0&&Has(t,@"^(?:да|давай|хочу|разговор|поговорить|выслушай|просто послушай|послушай|выговориться)$")){return new Reply("Тогда я слушаю. Расскажи, что произошло и что задело сильнее всего. Можно начать с одного момента 🧡");}
   if(age<=3&&context.Length>0&&Has(t,@"^(?:шаг|совет|что делать|помоги разобраться|следующий шаг)$"))return new Reply("Давай выберем одну ситуацию. Что в ней от тебя зависит и какое самое маленькое действие сейчас посильно? 🧡");
   if(age<=3&&context.Length>0&&Has(t,@"^(?:нет|не хочу|тишина|тихо|просто рядом|побудь рядом|не сейчас)$")){context="";return new Reply("Хорошо, рассказывать необязательно. Устроюсь рядом тихонько 🧡");}
   if(Has(t,@"что такое|что значит|кто такой|объясни")&&Has(t,@"п[еи]сс?имизм\w*|п[еи]сс?имис\w*"))return new Reply("Пессимизм — склонность ожидать неблагоприятного исхода и замечать трудности. Это способ смотреть на ситуацию, а не диагноз и не обязательная черта навсегда 🧡");
   string originalMood=t;t=Regex.Replace(t,@"\b(?:(?:больше )?не\s+(?:груст\w*|злюсь|боюсь|тревож\w*|п[еи]сс?имис\w*|волнуюсь)|перестал\w*\s+(?:бояться|волноваться|грустить))\b","");
   // Do not assign the speaker's feelings from a quotation or a report about somebody else.
   if(Has(t,@"он|она|они|друг|подруга|мама|папа")&&!Has(t,@"я|мне|меня|чувствую"))return null;
   foreach(var f in feelings){if(!Has(t,f.Pattern))continue;context=f.Key;age=0;return new Reply(Pick(f.Key,f.Answers).TrimEnd()+ (f.Answers[0].Contains("🧡")?"":" 🧡"));}
   if(t!=originalMood)return new Reply("Поняла, сейчас это чувство тебя не описывает. А какое настроение ближе? 🧡");return null;
  }
 }
}
